[
  {
    "text": "The lighthouse keeper climbed the stairs\nevery evening at seven.",
    "time_start": "00:01",
    "time_end": "00:05"
  },
  {
    "text": "He counted 112 steps,\nand never once lost count.",
    "time_start": "00:07",
    "time_end": "00:12"
  },
  {
    "text": "From the top, the harbor lights looked\nlike a string of small yellow beads.",
    "time_start": "00:13",
    "time_end": "00:18"
  },
  {
    "text": "On clear nights he could see the ferry\nleaving for the island.",
    "time_start": "00:21",
    "time_end": "00:25"
  },
  {
    "text": "That is all for tonight.",
    "time_start": "00:26",
    "time_end": "00:28"
  }
]
